from save_review import save
import json,re
from pathlib import Path
D=Path(__file__).resolve().parents[2];corpus={a['number']:a for a in json.loads((D/'全书分段底稿.json').read_text())}
def tables(n,ed,start,skip=()):
 bs={int(b['id'][-4:]):b for b in corpus[n]['blocks']};ts=[]
 for i,b in bs.items():
  if i<start or b.get('language')!='en' or i+1 not in bs or bs[i+1].get('language')!='zh':continue
  en=re.split(r' - | — | / |\(former\)',b['text'],maxsplit=1)[0].strip()
  zh=re.split(r' - |——| / |（|\(',ed.get(i+1,bs[i+1]['text']),maxsplit=1)[0].strip()
  if en and zh and len(en)<60 and en not in skip:ts.append((en,zh))
 return ts
ed={2:'死亡世界，即δτ类世界，是一类以本土动植物极度危险、攻击性极强而著称的星球。英文名称为 Death World，也写作 Deathworld。其生态系统在持续毁灭与迅速繁殖之间维系着微妙的平衡。死亡世界的形态多种多样：有些密布丛林，遍生食肉动植物，宛如地狱；有些则是离子风暴肆虐的荒芜火山废土。其中最著名、也最令人闻风丧胆的，就是地狱般的卡塔昌。',6:'有些星球会因外力变成死亡世界。例如，因迪加的大量圈养巨型掠食动物逃出动物园，便使整颗星球沦为此类环境。这种世界被称为“人造死亡世界”。',8:'人类能够、也确实在这些世界上生存，但必须永无止境地挣扎。在许多死亡世界，整颗星球的生物仿佛都有意敌视人类定居，集中力量消灭外来者。存在人类聚落或殖民地的死亡世界，人口可能从一千人到一千五百万人不等。',10:'死亡世界通常无人居住，也几乎无法殖民，但仍需勘探，因此必须建立前哨站及其他支援设施。有些星球富含矿产、动物、植物或气体资源，其什一税等级可能介于 Solutio Tertius 与 Solutio Prima 之间，原稿暂译“第三级初等”至“第三级上等”。',12:'某些帝国簿册将死亡世界记作 In Articulo Mortis，意为“临死之际”。卡利班在毁灭前就曾被如此记载。',18:'阿尔弗罗斯特——极限星域；乌鸦次星区。',21:'巴尔——极限星域；巴尔星系；人口12.2万。',23:'巴尔二号——巴尔的两颗卫星之一。',28:'卡尔德拉——极限星域。',30:'卡利班（已毁灭）——朦胧星域；暗黑天使的母星。',33:'卡塔昌——极限星域；人口1200万；卡塔昌丛林斗士的故乡。',38:'科瑞塔西亚——撕肉者战团的母星。',45:'登卡里次星——热带世界。帝国部队曾在此对抗格鲁格哈克大蛮干！参战部队包括泰卡恩第十一重型坦克连。',47:'登卡里一号——死亡世界，帝国部队曾在此与敌军交战。参战部队包括泰卡恩第九十装甲团、帝国海军第二十三轰炸机联队、死亡兵团第一二三装甲团，以及装备马卡里乌斯重型坦克的第十五重型连。',51:'费德里德——朦胧星域；卡利西斯星区、马尔坎边区；也是蛮荒世界。',58:'格雷戈恩——朦胧星域；阿斯凯隆星区、赛克洛皮亚次星区；也是蛮荒世界与丛林世界，有大量欧克兽人活动。',60:'哈德拉克——朦胧星域；卡利西斯星区、德鲁苏斯边区；也是机械修会探察基地和小型铸造世界。',63:'艾克斯——极限星域；奥特拉玛；原为乐土世界和农业世界。',65:'因迪加——原为动物园世界。',70:'卡里克——朦胧星域；卡利西斯星区、马尔坎边区；也是冰雪世界。',72:'凯诺夫三号——朦胧星域；卡利西斯星区、马尔菲次星区。',84:'Lost Hope 失落希望',97:'米德加迪亚（已毁灭）——朦胧星域；芬里斯星系；人口65亿。',102:'莫特雷萨——阿德兰提斯次星区。',108:'夜曲星——极限星域；人口1500万。',110:'诺克斯·阿尔法——太阳星域；莫比亚星区；莫比亚领地的边缘世界。莫比亚第六团在此遭纳垢腐化，沦为叛军。',112:'菲尔——朦胧星域；卡利西斯星区、哈冼录深渊。',116:'普拉克赛特尔——极限星域。',118:'派索斯——极限星域；得墨忒耳星区、潘多拉克斯星系。',120:'萨加西坦二号——极限星域；灾祸降临星系；也是风暴忠嗣军的训练设施所在地。',128:'忒提斯（土卫三）——太阳星域；太阳星区、太阳次星区、太阳星系；土星的卫星，被审判庭列为机密对象。',130:'特雷戈——星域归属不明，位于太阳星域边界之外不远处；昆提卢斯的征募世界。',139:'悲哀星——朦胧星域；卡利西斯星区、约西亚疆域。',141:'扬特——朦胧星域；阿斯凯隆星区、冥河星群。'}
bs={int(b['id'][-4:]):b for b in corpus[869]['blocks']}
for i,b in bs.items():
 if i<15 or b.get('language')!='en' or i+1 not in bs or bs[i+1].get('language')!='zh':continue
 t=ed.get(i+1,bs[i+1]['text'])
 if 'Sub-Sector' in b['text'] or 'Subsector' in b['text'] or 'Sub-sector' in b['text']:t=t.replace('亚星区','次星区').replace('分区','次星区')
 if t!=bs[i+1]['text']:ed[i+1]=t
save(869,ed,notes={2:'Death World 指生态极端危险的死亡世界，区别于 Dead World（死寂世界）。',8:'as if 是比喻，不能把整颗星球确有统一意识当成事实。原人口数字格式一并修正。',23:'Baal Secundus 是巴尔双卫星之一，原译“双子星”会使人误以为是恒星。',31:'Canak 与后列 Kanak 的英文不同，是否为同名变体尚待核，未据中文相似直接合并。',45:'原译把帝国参战部队写成了星球本身“包括”这些单位，已恢复修饰关系。',47:'原英文第十五重型连与第一二三装甲团之间的隶属关系标点含糊，暂列出所见单位，未断言独立建制；待核。',84:'Lost 是失落，不是 Last（最后）；原“最后希望”误译。',110:'原译只剩行星名，补回星域、星区与莫比亚第六团堕落的整段信息。',116:'Ultima Segmentum 为极限星域，原译朦胧星域错误。',128:'补回原译遗漏的审判庭机密对象状态。'},terms=[('Death World','死亡世界'),('Deathworld','死亡世界'),('Man-Made Death World','人造死亡世界'),('In Articulo Mortis','临死之际'),('Lost Hope','失落希望'),('Menagerie World','动物园世界'),('Waaagh! Grughakh','格鲁格哈克大蛮干！'),('Tekarn','泰卡恩')]+tables(869,ed,15,skip=('Belisarius IV',)),additions={14:'十三号（XIII；暂定译名）',131:'UB-26（行星编号）'})
ed={2:'蛮荒世界，即φλ类世界，是帝国对最原始的人类世界的分类。',7:'蛮荒世界的居民往往因长期隔绝，早已退回原始的社会状态。其科技水平停留在火药发明之前，甚至仍处于石器时代。许多居民以狩猎采集为生，使用原始工具与武器；几乎所有这类世界的人类文化，都围绕部族、帮派或信仰群体之间的关系展开。',9:'蛮荒世界居民适应了严酷环境，是帝国卫队与阿斯塔特的理想征募来源。有时，某颗蛮荒世界位于战区，居民便会被征入帝国卫队；获选战士只接受激光或实弹武器操作的基础训练。不过，更常见的是当地人被选入各星际战士战团的征募计划。蛮荒世界出身的卫兵通常是部族战士，由本氏族长老作为什一税献给帝国卫队。有些人会在大型训练营或舰船舱室内接受集体训练；有些人只是被人演示一遍激光枪的用法，就被认为能够自行应付。另一些人则由族人教导，通过死记硬背的程式和宗教仪式学习战斗。',11:'与所有帝国世界一样，蛮荒世界也由行星总督统治，但这里的总督与其他类型世界的总督很不一样。他们几乎总是与土著分开居住，通常住在一座由外来者占据的城市，或在轨道上定居；他们通常只在需要压低灵能者与变种人的数量时，才直接干预当地事务。宗教异端也是长期隐患，尤其常见于尚武教派，因此国教人员必须保持警惕，并定期调整当地信仰。总督及常驻人员自身也受到严密监视，以防他们被本土文化同化。尤其当居民的信仰被操纵、把总督奉为“神明”时，这种监视更为必要。',13:'与外来者接触所带来的文化冲击，是蛮荒世界面临的另一个问题。把一个土著带离故乡，让他接触亚空间航行等事物，可能使他不知所措，甚至发疯。进入更广阔帝国社会的蛮荒世界居民，往往仍保留原有迷信和部族习惯，有时因此难以融入社会：例如执着于保存死去战友的骨骸，或调配、经常涂抹气味恶臭的战绘颜料。另一些习惯——例如近乎狂热地怀疑与厌恶“巫术”——在帝国看来却可能有用且明智。',15:'蛮荒世界的什一税等级较低，通常为 Solutio Tertius，原稿暂译“第三级初等”。人口介于10万至500万之间。',32:'黑水星——极限星域；洛基星区、林恩星系；帝国；绯红之拳的征募世界。',38:'巧高里斯（蒙杜斯·普兰努斯）——极限星域；帝国；人口1000万；也是沙漠世界。',40:'科索尼亚——太阳星域；帝国；毁灭前人口约20亿；星际战士母星。',42:'库亚维尔——朦胧星域；卡利西斯星区、边陲；由赛维安帝国控制。',48:'黄昏星——朦胧星域；卡利西斯星区、马尔菲次星区、黄昏星系；帝国。',50:'德维姆里奇——朦胧星域；卡利西斯星区、哈冼录深渊；帝国。',54:'费德里德——朦胧星域；卡利西斯星区、马尔坎边区；帝国；也是死亡世界。',56:'芬里斯——底稿星域栏并列朦胧星域与太阳星域；帝国；也是死亡世界和星际战士母星。',60:'加尔加西亚三号——极限星域；大漩涡区域、凯马拉流域、加尔加西亚星系；帝国。',72:'克努索尔——帝国／欧克兽人；曾遭荡平。',76:'莉莉娅世界——帝国；人口450万。',88:'斯凯鲁斯——朦胧星域；卡迪亚星区；帝国；星际战士母星。',92:'斯特兰克——朦胧星域；卡利西斯星区、戈尔根纳疆域；帝国。',98:'提丰主星——极限星域；科里亚尼斯星区、奥瑞利亚次星区、提丰星系；原属帝国。底稿记人口30万；现为死寂世界，过去也是丛林世界和血鸦的征募世界。',102:'瓦洛斯·科林——朦胧星域；卡利西斯星区、哈冼录深渊；帝国。',106:'维索尔——朦胧星域；斯卡鲁斯星区、安提玛次星区、维索尔星系；帝国。',108:'沃隆克斯——朦胧星域；卡利西斯星区、阿德兰提斯次星区；帝国。',110:'泽巴斯次星——暴风星域；帝国；星际战士母星。'}
save(870,ed,notes={7:'Stone Age 为石器时代，原译“石器时代以前”把技术水平进一步倒退，已纠正。',9:'stub-weaponry 在此指实弹武器，不是泛指弹药；rote-learned 指死记硬背，不等于信仰狂热。',11:'only interfering 修饰总督的干预方式，不是住在轨道上的目的。',13:'noxious-smelling 描写难闻气味，不能据此断定颜料一定有毒。',42:'依核心术语统一 Severan Dominate＝赛维安帝国。',56:'原英文并列 Obscurus 与 Solar，未提供版本或时期解释，保留源文分歧待核。',60:'原译漏掉 Gargathea System，已补回。Khymaran Drift 暂译凯马拉流域，非河流实地判断。',72:'Scoured 是遭到荡平，不是“被搜寻”。',98:'人口记录与现为死寂世界的状态可能属于不同时间，保留资料差异。',110:'原译重复“星际战士修会”，按 Space Marine Homeworld 改为星际战士母星。'},terms=[('Feral World','蛮荒世界'),('Solutio Tertius','第三级初等'),('Solutio Prima','第三级上等'),('Khymaran Drift','凯马拉流域')]+tables(870,ed,17))
